if ($sheetIndex === null) {
    if ($this->activeSheetIndex < 0) {
        $this->activeSheetIndex = count($this->workSheetCollection);
    }
    $this->workSheetCollection[] = $worksheet;
} else {
    $sheetCount = count($this->workSheetCollection);
    if ($sheetIndex < 0) {
        $insertionIndex = max(0, $sheetCount + $sheetIndex);
    } else {
        $insertionIndex = min($sheetIndex, $sheetCount);
    }

    // Insert the sheet at the requested index
    array_splice(
        $this->workSheetCollection,
        $insertionIndex,
        0,
        [$worksheet]
    );

    // Adjust active sheet index if necessary
    if ($this->activeSheetIndex < 0) {
        $this->activeSheetIndex = $insertionIndex;
    } elseif ($this->activeSheetIndex >= $insertionIndex) {
        ++$this->activeSheetIndex;
    }
}

